<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/health_network_v590.php';if(!hn590_enabled()){http_response_code(404);exit;}$flash='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hn590_bool('health_network_v590_ambulance_requests',true)){http_response_code(403);exit('Online ambulance requests are disabled.');}try{csrf_check();$u=hn590_require_login('/ambulance.php');$rid=hn590_create_ambulance_request((int)$u['id'],trim((string)($_POST['pickup_address']??'')),trim((string)($_POST['destination']??'')),trim((string)($_POST['contact_phone']??'')),trim((string)($_POST['request_note']??'')),isset($_POST['pickup_lat'])&&$_POST['pickup_lat']!==''?(float)$_POST['pickup_lat']:null,isset($_POST['pickup_lng'])&&$_POST['pickup_lng']!==''?(float)$_POST['pickup_lng']:null);$flash='Ambulance request sent to the dispatch desk. Reference #'.$rid.'.';}catch(Throwable $e){$error=$e->getMessage();}}$fleet=hn590_ambulances(false);$em=hn590_setting('health_network_v590_emergency_number',hn590_setting('doctor_online_v580_emergency_number','1122'));hn590_track('ambulance_page');hn590_public_header('Ambulance & Emergency Desk','Request local ambulance dispatch and view fleet availability.');
?><main><section class="hn590-pagehero ambulance"><div class="hn590-shell hn590-amb-hero"><div><span>AMBULANCE & EMERGENCY DESK</span><h1>Request transport. Track dispatch status.</h1><p>Submit a pickup request to configured local ambulance providers. For life-threatening emergencies, call emergency services immediately.</p></div><a class="hn590-big-call" href="tel:<?=e(preg_replace('/[^0-9+]/','',$em)?:$em)?>"><i></i><span>EMERGENCY CALL</span><b><?=e($em)?></b></a></div></section><section class="hn590-section"><div class="hn590-shell hn590-two"><?php if($flash):?><div class="hn590-alert ok span2"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="hn590-alert err span2"><?=e($error)?></div><?php endif;?><section class="hn590-form-card"><span>REQUEST DESK</span><h2>Ambulance request</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Pickup location<input name="pickup_address" required placeholder="Street / landmark / area"></label><label>Destination (optional)<input name="destination" placeholder="Hospital / clinic / destination"></label><label>Contact phone<input name="contact_phone" required></label><label>Operational note<textarea name="request_note" placeholder="Access/gate/landmark details only; do not rely on this field for emergency medical triage."></textarea></label><input type="hidden" name="pickup_lat" data-hn-lat><input type="hidden" name="pickup_lng" data-hn-lng><button type="button" class="hn590-btn" data-hn-location>⌖ Use My Location</button><button class="hn590-btn danger">Send Dispatch Request</button></form><p class="hn590-warning">This online request is not a guaranteed emergency-response channel. Call emergency services for urgent/life-threatening situations.</p></section><section><div class="hn590-head"><div><span>FLEET STATUS</span><h2>Configured ambulances</h2></div></div><div class="hn590-fleet public"><?php if(!$fleet):?><div class="hn590-empty">No fleet records published.</div><?php endif;?><?php foreach($fleet as $a):?><div><i class="<?=$a['availability']==='available'?'on':''?>">●</i><span><b><?=e($a['vehicle_no'])?></b><small><?=e($a['vehicle_type']?:'Ambulance')?> · <?=e($a['base_location']?:'Local base')?></small></span><em><?=e(strtoupper(str_replace('_',' ',$a['availability'])))?></em></div><?php endforeach;?></div></section></div></section></main><?php hn590_public_footer();?>
